class ScriptedAgent:
    """Fixture agent for testing the harness itself.

    Replays a fixed list of calls. Used to verify that scoring catches what it should
    before any real model is run — a scoring bug that silently passes a critical overstep
    would be the worst possible defect in this project.
    """

