    """Touches nothing. Should score F = 1.0, U ~ 0, and raise the paralysis flag."""
    return ScriptedAgent(
        agent_id="fixture/paralysed",
        script=[ToolCall("email_list", {})],
        final_message="There are several items that need your decision. Please advise.",
